#include "pov.h"

// AI: below section was generated by an AI
// Maps a strip LED index to an image row. BMP rows are stored bottom-up while
// GIF rows are stored top-down, so the "natural" orientation differs between
// formats. When USERMOD_POV_DISPLAY_FLIP_VERTICAL is defined at build time
// (e.g. -D USERMOD_POV_DISPLAY_FLIP_VERTICAL in platformio_override.ini), the
// image is mirrored vertically for both formats: LED 0 shows the opposite end
// of the image. Enable it when the image appears upside-down on the strip.
static inline uint16_t povImageRow(uint16_t ledIndex, uint16_t imgHeight) {
#ifdef USERMOD_POV_DISPLAY_FLIP_VERTICAL
  return imgHeight - 1 - ledIndex;
#else
  return ledIndex;
#endif
}
// AI: end

POV::POV() {}

bool POV::loadImage(const char * filename){
  size_t len = strlen(filename);
  if (len < 4) return false;
  const char* ext = filename + (len - 4);
#ifdef WLED_ENABLE_GIF
  bool isGif = (ext[0] == '.') && (ext[1] == 'g' || ext[1] == 'G') && (ext[2] == 'i' || ext[2] == 'I') && (ext[3] == 'f' || ext[3] == 'F');
  if (isGif) {
    image.unload(); // release the BMP image
    _useGif = true;
    if (!gifImage.init(filename)) return false;
    return gifImage.decodeFrame(); // decode the first frame
  }
  gifImage.unload(); // release the GIF image
  _useGif = false;
#endif
  if(!image.init(filename)) return false;
  if(!image.load()) return false;
  return true;
}

bool POV::isLoaded() {
#ifdef WLED_ENABLE_GIF
  return _useGif ? gifImage.isLoaded() : image.isLoaded();
#else
  return image.isLoaded();
#endif
}

int POV::width() {
#ifdef WLED_ENABLE_GIF
  return _useGif ? gifImage.width() : image.width();
#else
  return image.width();
#endif
}

bool POV::decodeNextFrame() {
#ifdef WLED_ENABLE_GIF
  if (_useGif) return gifImage.decodeFrame();
#endif
  return true; // static images have no next frame
}

char * POV::getFilename() {
#ifdef WLED_ENABLE_GIF
  return _useGif ? gifImage.getFilename() : image.getFilename();
#else
  return image.getFilename();
#endif
}

// Display a column directly from image memory
// For each pixel in the column (from row 0 to row height-1),
// compute its position in the BMP buffer and read the BGR values
void POV::showColumn(uint16_t colIndex) {
#ifdef WLED_ENABLE_GIF
    if (_useGif) {
      showColumnGif(colIndex);
      return;
    }
#endif
    // Ignore out-of-range columns: for widths == 2 (mod 4) the row-size check
    // below would still read one byte past the buffer when colIndex == width
    if (colIndex >= image.width()) return;
    uint16_t imgHeight = image.height();
    int rowSize = image.rowSize();
    
    // AI: below section was generated by an AI
    for (uint16_t i = 0; i < SEGLEN; i++) {
        if (i < imgHeight) {
            // Get pointer to this row in the image
            byte *rowStart = image.line(povImageRow(i, imgHeight));
            if (rowStart) {
                // Compute offset to the desired column (3 bytes per pixel: BGR)
                uint16_t pixelOffset = colIndex * 3;
                if (pixelOffset + 2 <= rowSize) {
                    // Read BGR values directly from image buffer
                    uint8_t b = rowStart[pixelOffset];
                    uint8_t g = rowStart[pixelOffset + 1];
                    uint8_t r = rowStart[pixelOffset + 2];
                    SEGMENT.setPixelColor(i, CRGB(r, g, b));
                    continue;
                }
	    }
	}
        // No valid pixel for this row/column: write black
        SEGMENT.setPixelColor(i, CRGB::Black);
    }
    // AI: end
}

#ifdef WLED_ENABLE_GIF
// AI: below section was generated by an AI
// Display a column from the decoded GIF frame buffer (packed RGB, no padding)
// Each LED is written exactly once: image rows get their pixel color, LEDs
// beyond the image height are set to black. Writing black first and then the
// color for the same LED would double the setPixelColor() work per column.
// The column is walked by row stride instead of calling pixel() per LED, which
// avoids a bounds check and a multiply per pixel.
void POV::showColumnGif(uint16_t colIndex) {
    // Ignore out-of-range columns
    if (colIndex >= gifImage.width()) return;
    uint16_t imgHeight = gifImage.height();
    const uint8_t * colBase = gifImage.columnPtr(colIndex);
    if (!colBase) { // image not loaded: clear the strip
      for (uint16_t i = 0; i < SEGLEN; i++) SEGMENT.setPixelColor(i, CRGB::Black);
      return;
    }
    size_t rowStride = (size_t)gifImage.width() * 3; // packed RGB: 3 bytes per pixel
    for (uint16_t i = 0; i < SEGLEN; i++) {
      if (i < imgHeight) {
        const uint8_t * px = colBase + (size_t)povImageRow(i, imgHeight) * rowStride;
        SEGMENT.setPixelColor(i, CRGB(px[0], px[1], px[2]));
      } else {
        SEGMENT.setPixelColor(i, CRGB::Black);
      }
    }
}
// AI: end
#endif
